using System;using System.Linq;using System.Collections.Generic;using System.Windows;using System.Windows.Input;using System.Windows.Media;
namespace FileCompass {
 internal sealed partial class DiskChart {
  internal bool Treemap;internal List<DiskChartRow> MapRows;internal event Action<DiskChartRow> SliceDoubleClicked;
  internal static List<Tuple<DiskChartRow,Rect>> MapLayout(IEnumerable<DiskChartRow> source,Rect bounds){var rows=source.Where(x=>x.Value>0).OrderByDescending(x=>x.Value).Take(2048).ToArray();var output=new List<Tuple<DiskChartRow,Rect>>();Layout(rows,0,rows.Length,bounds,output);return output;}
  static void Layout(DiskChartRow[] rows,int start,int count,Rect bounds,List<Tuple<DiskChartRow,Rect>> output){if(count==0||bounds.Width<=0||bounds.Height<=0)return;if(count==1){output.Add(Tuple.Create(rows[start],bounds));return;}double total=0;for(int i=start;i<start+count;i++)total+=rows[i].Value;double sum=rows[start].Value;int split=1;while(split<count-1&&sum+rows[start+split].Value/2<total/2)sum+=rows[start+split++].Value;double fraction=sum/total;if(bounds.Width>=bounds.Height){double width=bounds.Width*fraction;Layout(rows,start,split,new Rect(bounds.X,bounds.Y,width,bounds.Height),output);Layout(rows,start+split,count-split,new Rect(bounds.X+width,bounds.Y,bounds.Width-width,bounds.Height),output);}else{double height=bounds.Height*fraction;Layout(rows,start,split,new Rect(bounds.X,bounds.Y,bounds.Width,height),output);Layout(rows,start+split,count-split,new Rect(bounds.X,bounds.Y+height,bounds.Width,bounds.Height-height),output);}}
  void DrawMap(DrawingContext dc){foreach(var item in MapLayout(MapRows??Rows,new Rect(0,0,Math.Max(0,ActualWidth),Math.Max(0,ActualHeight)))){var row=item.Item1;var rect=item.Item2;var geometry=new RectangleGeometry(rect);hits.Add(Tuple.Create(row,(Geometry)geometry));dc.DrawRectangle(row.Color??ColorFor(row.Key??row.Name),new Pen(CompactTheme.WhiteSurface,1),rect);if(hovered==row)dc.DrawRectangle(null,new Pen(FluentTheme.Text,2),rect);if(rect.Width>45&&rect.Height>28){Text(dc,row.Name,new Point(rect.Left+5,rect.Top+4),Brushes.White,rect.Width-10,11,false);if(rect.Height>45)Text(dc,row.Size,new Point(rect.Left+5,rect.Top+21),Brushes.White,rect.Width-10,10,false);}}}
  protected override void OnMouseLeftButtonDown(MouseButtonEventArgs e){base.OnMouseLeftButtonDown(e);if(e.ClickCount==2){var row=Hit(e.GetPosition(this));if(row!=null&&SliceDoubleClicked!=null){SliceDoubleClicked(row);e.Handled=true;}}}
 }
}
